mapper.select:
select id, user_id, name, created_at, updated_at, deleted
from pw_deck
where id = #{id}
  and user_id = #{userId}
  and deleted = 0
limit 1

mapper.update:
update pw_deck
set name = #{name}
where id = #{id}
  and user_id = #{userId}
  and deleted = 0

mapper.delete:
delete from pw_deck
where id = #{id}
  and user_id = #{userId}
